function getAlarmTypeText(mainType, minorType) {
  const mainTypeInfo = alarmTypeMap[mainType];
  if (!mainTypeInfo) {
    return {
      mainTypeText: mainType ? '未知主类型(' + mainType + ')' : '',
      minorTypeText: minorType ? '未知子类型(' + minorType + ')' : ''
    };
  }
  const minorTypeText = minorType && mainTypeInfo.minorTypes[minorType]
    ? mainTypeInfo.minorTypes[minorType]
    : (minorType ? '未知子类型(' + minorType + ')' : '');
  return { mainTypeText: mainTypeInfo.mainName, minorTypeText };
}

module.exports = { alarmTypeMap, getAlarmTypeText };
